<?php

namespace App\Models;

use App\Enums\Transport;
use Database\Factories\GatewayFactory;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Attributes\Hidden;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * A vendor SIP endpoint. `name` becomes the FreeSWITCH gateway name.
 * The password is encrypted with the app key, so FreeSWITCH config for
 * gateways is generated by Laravel rather than read from the table.
 */
#[Hidden(['password'])]
#[Fillable(['trunk_id', 'name', 'host', 'port', 'transport', 'username', 'password', 'register', 'enabled', 'priority', 'weight'])]
class Gateway extends Model
{
    /** @use HasFactory<GatewayFactory> */
    use HasFactory;

    protected function casts(): array
    {
        return [
            'port' => 'integer',
            'transport' => Transport::class,
            'password' => 'encrypted',
            'register' => 'boolean',
            'enabled' => 'boolean',
            'priority' => 'integer',
            'weight' => 'integer',
        ];
    }

    public function trunk(): BelongsTo
    {
        return $this->belongsTo(Trunk::class);
    }
}
